@lru_cache(None)
def decomposable(facets, k):
    if len(facets) == 1:
        return True
    candidates=set()
    for f in facets:
        s=f
        while s:
            if s.bit_count() <= k+1:
                candidates.add(s)
            s=(s-1)&f
    for s in candidates:
        deletion=tuple(f for f in facets if f&s != s)
        if not deletion:
            continue
        # The maximal faces of the deletion not already original facets
        # are among f\{v}, with s contained in f and v in s.
        if any(not any(((f^v)&g)==(f^v) for g in deletion)
               for f in facets if f&s == s for v in bits(s)):
            continue
        link=tuple(sorted({f^s for f in facets if f&s == s}))
        if decomposable(deletion,k) and decomposable(link,k):
            return True
    return False

def exhaustive(n,d,k):
    universe=[sum(1<<v for v in c) for c in combinations(range(n),d+1)]
    N=len(universe)
    good=set()
    for m in range(1,1<<N):
        facets=tuple(sorted(universe[i] for i in range(N) if m>>i&1))
        if decomposable(facets,k):
            good.add(m)
    full=(1<<N)-1
    reaches={full}
    for m in sorted(good,key=int.bit_count,reverse=True):
        if m==full:
            continue
        if any((m|(1<<i)) in reaches for i in range(N) if not(m>>i&1)):
            reaches.add(m)
    assert reaches==good
    print(f'n={n}, d={d}, k={k}: {len(good)} decomposable complexes; all completable')
